-- ---------------------------------------------------------------- RAW
CREATE TABLE IF NOT EXISTS RAW.ST_SITE (
    ID                       VARCHAR NOT NULL,
    NAME                     VARCHAR,
    SITE_NAME__C             VARCHAR,
    MARKET__C                VARCHAR,
    CUSTOMER__C              VARCHAR,
    STREET__C                VARCHAR,
    CITY__C                  VARCHAR,
    STATE__C                 VARCHAR,
    ZIP__C                   VARCHAR,
    LATITUDE__C              NUMBER(18,4),
    LONGITUDE__C             NUMBER(18,4),
    STRUCTURE_TYPE__C        VARCHAR,
    STRUCTURE_HEIGHT_FT__C   NUMBER(18,4),
    STRUCTURE_OWNER__C       VARCHAR,
    SITE_STATUS__C           VARCHAR,
    LOADED_AT                TIMESTAMP_TZ,
    CONSTRAINT PK_ST_SITE PRIMARY KEY (ID)
) COMMENT = 'SiteTracker Site export';

CREATE TABLE IF NOT EXISTS RAW.ST_PROJECT (
    ID                       VARCHAR NOT NULL,
    NAME                     VARCHAR,
    SITE__C                  VARCHAR,
    PROJECT_TYPE__C          VARCHAR,
    SCOPING_SERVICE_LINE__C  VARCHAR,
    SCOPING_ASSIGNED_DATE__C VARCHAR,
    BOM_STATUS__C            VARCHAR,
    CURRENT_BOM_REV__C       VARCHAR,
    CX_SERVICE_PROVIDER__C   VARCHAR,
    SCOPING_COMPLETE_FORECAST__C VARCHAR,
    SCOPING_COMPLETE_ACTUAL__C VARCHAR,
    FBA_DATE__C              VARCHAR,
    LOADED_AT                TIMESTAMP_TZ,
    CONSTRAINT PK_ST_PROJECT PRIMARY KEY (ID)
) COMMENT = 'SiteTracker Project export';

CREATE TABLE IF NOT EXISTS RAW.ST_MILESTONE (
    ID                       VARCHAR NOT NULL,
