    CONSTRAINT PK_SITE_REQUIREMENT PRIMARY KEY (SITE_ID, RUN_ID)
) COMMENT = 'Access, rigging and hold requirements';

CREATE TABLE IF NOT EXISTS CORE.ESTIMATE (
    SITE_ID                  VARCHAR NOT NULL,
    RUN_ID                   VARCHAR NOT NULL,
    CYCLE_DAYS               NUMBER(18,4),
    SERVICES_USD             NUMBER(18,4),
    MATERIAL_USD             NUMBER(18,4),
    TOTAL_USD                NUMBER(18,4),
    DETAIL                   VARIANT,
    CONSTRAINT PK_ESTIMATE PRIMARY KEY (SITE_ID, RUN_ID)
) COMMENT = 'Cost and cycle-time estimate';

CREATE TABLE IF NOT EXISTS CORE.EHS_ALERT (
    ALERT_ID                 VARCHAR NOT NULL,
    SITE_ID                  VARCHAR NOT NULL,
    RULE_ID                  VARCHAR,
    SEVERITY                 VARCHAR,
    ALERT_TEXT               VARCHAR,
    STATUS                   VARCHAR,
    CREATED_AT               TIMESTAMP_TZ,
    UPDATED_AT               TIMESTAMP_TZ,
    UPDATED_BY               VARCHAR,
    CONSTRAINT PK_EHS_ALERT PRIMARY KEY (ALERT_ID)
) COMMENT = 'EH&S alerts (rooftop crane, guyed tower, SA fail)';

CREATE TABLE IF NOT EXISTS CORE.REDLINE (
    REDLINE_ID               VARCHAR NOT NULL,
    SITE_ID                  VARCHAR NOT NULL,
    DISC_ID                  VARCHAR,
    DOC_TYPE                 VARCHAR,
    DOC_REVISION             VARCHAR,
    SHEET                    VARCHAR,
    MARKUP                   VARCHAR,
    CHANGE_FROM              VARCHAR,
    CHANGE_TO                VARCHAR,
    STATUS                   VARCHAR,
    PDF_PATH                 VARCHAR,
    CREATED_AT               TIMESTAMP_TZ,
    UPDATED_AT               TIMESTAMP_TZ,
    UPDATED_BY               VARCHAR,
    CONSTRAINT PK_REDLINE PRIMARY KEY (REDLINE_ID)
) COMMENT = 'Redlines to apply to CD / MA documents';

CREATE TABLE IF NOT EXISTS CORE.RFI (
    RFI_ID                   VARCHAR NOT NULL,
    SITE_ID                  VARCHAR NOT NULL,
    TO_PARTY                 VARCHAR,
    SUBJECT                  VARCHAR,
    QUESTION                 VARCHAR,
    PROPOSED_ANSWER          VARCHAR,
    ANSWER                   VARCHAR,
    DISC_IDS                 VARIANT,
    STATUS                   VARCHAR,
    CREATED_AT               TIMESTAMP_TZ,
    UPDATED_AT               TIMESTAMP_TZ,
    UPDATED_BY               VARCHAR,
    CONSTRAINT PK_RFI PRIMARY KEY (RFI_ID)
) COMMENT = 'Requests for information';

-- ---------------------------------------------------------------- WF
CREATE TABLE IF NOT EXISTS WF.WORKFLOW_EVENT (
    EVENT_ID                 VARCHAR NOT NULL,
    ENTITY_TYPE              VARCHAR NOT NULL,
    ENTITY_ID                VARCHAR NOT NULL,
    SITE_ID                  VARCHAR,
    FROM_STATE               VARCHAR,
    ACTION                   VARCHAR,
    TO_STATE                 VARCHAR,
    ACTOR_USER_ID            VARCHAR,
    ACTOR_ROLE               VARCHAR,
    REASON_CODE              VARCHAR,
    COMMENT                  VARCHAR,
    EVENT_TS                 TIMESTAMP_TZ,
    CORRELATION_ID           VARCHAR,
    CONSTRAINT PK_WORKFLOW_EVENT PRIMARY KEY (EVENT_ID)
) COMMENT = 'Every workflow transition (status history)';

CREATE TABLE IF NOT EXISTS WF.NOTIFICATION (
    NOTIFICATION_ID          VARCHAR NOT NULL,
    ROLE_CODE                VARCHAR,
    USER_ID                  VARCHAR,
    SITE_ID                  VARCHAR,
    ENTITY_TYPE              VARCHAR,
    ENTITY_ID                VARCHAR,
    MESSAGE                  VARCHAR,
    CREATED_AT               TIMESTAMP_TZ,
    READ_AT                  TIMESTAMP_TZ,
    CONSTRAINT PK_NOTIFICATION PRIMARY KEY (NOTIFICATION_ID)
) COMMENT = 'Role inbox items created by transitions';

CREATE TABLE IF NOT EXISTS WF.COMMENT (
    COMMENT_ID               VARCHAR NOT NULL,
    ENTITY_TYPE              VARCHAR,
    ENTITY_ID                VARCHAR,
    SITE_ID                  VARCHAR,
    USER_ID                  VARCHAR,
    COMMENT_TEXT             VARCHAR,
    CREATED_AT               TIMESTAMP_TZ,
    CONSTRAINT PK_COMMENT PRIMARY KEY (COMMENT_ID)
) COMMENT = 'Free-text comments';

-- ---------------------------------------------------------------- AUDIT
CREATE TABLE IF NOT EXISTS AUDIT.AUDIT_LOG (
    AUDIT_ID                 VARCHAR NOT NULL,
    EVENT_TS                 TIMESTAMP_TZ,
    ENTITY_TYPE              VARCHAR,
    ENTITY_ID                VARCHAR,
    SITE_ID                  VARCHAR,
    ACTION                   VARCHAR,
    ACTOR_USER_ID            VARCHAR,
    ACTOR_ROLE               VARCHAR,
    REASON_CODE              VARCHAR,
    COMMENT                  VARCHAR,
    BEFORE_VALUE             VARIANT,
    AFTER_VALUE              VARIANT,
    CORRELATION_ID           VARCHAR,
    SOURCE                   VARCHAR,
    CONSTRAINT PK_AUDIT_LOG PRIMARY KEY (AUDIT_ID)
) COMMENT = 'Who changed what, when and why (immutable)';

CREATE TABLE IF NOT EXISTS AUDIT.APP_LOG (
    LOG_ID                   VARCHAR NOT NULL,
    LOG_TS                   TIMESTAMP_TZ,
    LEVEL                    VARCHAR,
    LOGGER                   VARCHAR,
    MESSAGE                  VARCHAR,
    CORRELATION_ID           VARCHAR,
    USER_ID                  VARCHAR,
    SITE_ID                  VARCHAR,
    COMPONENT                VARCHAR,
    DETAIL                   VARIANT,
    CONSTRAINT PK_APP_LOG PRIMARY KEY (LOG_ID)
) COMMENT = 'Application log sink (level set per environment)';

CREATE TABLE IF NOT EXISTS AUDIT.ERROR_LOG (
    ERROR_ID                 VARCHAR NOT NULL,
    ERROR_TS                 TIMESTAMP_TZ,
    ERROR_CODE               VARCHAR,
    MESSAGE                  VARCHAR,
    EXCEPTION_TYPE           VARCHAR,
    STACK                    VARCHAR,
    WHERE_RAISED             VARCHAR,
    CORRELATION_ID           VARCHAR,
    USER_ID                  VARCHAR,
    SITE_ID                  VARCHAR,
    COMPONENT                VARCHAR,
    DETAILS                  VARIANT,
    CONSTRAINT PK_ERROR_LOG PRIMARY KEY (ERROR_ID)
) COMMENT = 'Errors with stack and context';

